/// <summary>
/// Update UOM for pick quantity when sales unit is not EA.
/// </summary>
/// <param name = "_entityCtx">_entityCtx</param>
/// <param name = "_dataSourceCtx">_dataSourceCtx</param>
/// <returns>boolean value</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    const str defaultUOM = "EA";

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(METPickDirectorDataEntitity, METPickDirectorData))
    {
        SalesLine salesLine = SalesLine::find(this.SalesId, this.LineNum);
        SalesUnit salesUnit = salesLine.SalesUnit;

        if (salesUnit != defaultUOM)
        {
            METPurchaseWMSFactor factor = UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(salesUnit).RecId, UnitOfMeasure::findBySymbol(defaultUOM).RecId, EcoResProduct::findByProductNumber(salesLine.ItemId).RecId).Factor;

            this.QtyPicked = this.QtyPicked * factor;
        }
    }

    ret = super(_entityCtx, _dataSourceCtx);

    return ret;
}

/// <summary>
/// At the end of the import process do the sales order reservation and pick list process for the pick director wave file data.
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">_dmfDefinitionGroupExecution</param>
public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    METPickDirectorDataController pickDirectorcontroller = new METPickDirectorDataController();
    pickDirectorcontroller.processSOForPickDirectorData(_dmfDefinitionGroupExecution);
}
